        else:
            results.append(f"{drift_type}.{path}")

    def drift(exp, act, prefix):
        all_keys = set(exp.keys()) | set(act.keys())
        for key in all_keys:
            path = f"{prefix}.{key}" if prefix else key
            if key not in act:
                report_leaves(exp[key], path, "missing")
